const $=s=>document.querySelector(s);
const apps={chat:['▤','AI Chat','#ffffa0'],notes:['▧','Notepad','#fff'],calc:['▦','Calculator','#b0d0ff'],paint:['✎','Paint','#ffff60'],settings:['⚙','Settings','#ddd']};
const windows=new Map();let topZ=1,key='',settings=JSON.parse(localStorage.getItem('desktop95-settings')||'{}');
