function el(tag,attrs={},text){const e=document.createElement(tag);Object.assign(e,attrs);if(text!==undefined)e.textContent=text;return e}
function download(name,data,type='text/plain'){const a=el('a',{href:URL.createObjectURL(new Blob([data],{type})),download:name});a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
