function open(id){desktopSound.play('open');$('#start-menu').hidden=true;if(windows.has(id)){focus(id);return}const meta=apps[id]||['▣','Welcome to Desktop 95','#fff'];const w=el('section',{className:'window',role:'dialog','ariaLabel':meta[1]});w.setAttribute('aria-label',meta[1]);w.style.left=(145+windows.size*28)+'px';w.style.top=(44+windows.size*24)+'px';const bar=el('div',{className:'titlebar'});bar.append(el('span',{},meta[0]),el('strong',{},meta[1]));const min=el('button',{title:'Minimize'},'_'),max=el('button',{title:'Maximize'},'□'),close=el('button',{title:'Close'},'×');bar.append(min,max,close);const content=el('div',{className:'content'}),status=el('div',{className:'status'},'Ready');w.append(bar,content,status);const task=el('button',{},meta[0]+' '+meta[1]);$('#tasks').append(task);$('#desktop').append(w);windows.set(id,{w,task});w.addEventListener('pointerdown',()=>focus(id));task.onclick=()=>w.hidden?focus(id):(w.hidden=true,task.classList.remove('pressed'));min.onclick=()=>{w.hidden=true;task.classList.remove('pressed')};max.onclick=()=>w.classList.toggle('maximized');close.onclick=()=>{desktopSound.play('close');w.remove();task.remove();windows.delete(id)};bar.ondblclick=()=>w.classList.toggle('maximized');bar.onpointerdown=e=>{if(e.target.closest('button')||w.classList.contains('maximized'))return;const x=e.clientX-w.offsetLeft,y=e.clientY-w.offsetTop;bar.setPointerCapture(e.pointerId);bar.onpointermove=m=>{w.style.left=Math.max(0,Math.min(innerWidth-80,m.clientX-x))+'px';w.style.top=Math.max(0,Math.min(innerHeight-85,m.clientY-y))+'px'};bar.onpointerup=()=>bar.onpointermove=null};focus(id);
if(id==='notes'){const tools=el('div',{className:'row'}),save=el('button',{},'Save as .txt'),text=el('textarea',{value:localStorage.getItem('desktop95-notes')||'',placeholder:'Write something…',ariaLabel:'Notes'});tools.append(save);content.append(tools,text);text.oninput=()=>{localStorage.setItem('desktop95-notes',text.value);status.textContent=text.value.length+' characters · Saved on this browser'};save.onclick=()=>download('Notes.txt',text.value);status.textContent='Notes are saved automatically on this browser.'}
else if(id==='calc'){w.style.width='310px';const display=el('input',{className:'calc-display',readOnly:true,value:'0',ariaLabel:'Calculator display'}),keys=el('div',{className:'keys'});let a=null,op=null,fresh=true;const operate=()=>{const b=Number(display.value);if(a===null)return b;return op==='+'?a+b:op==='−'?a-b:op==='×'?a*b:a/b};for(const n of ['C','±','%','÷','7','8','9','×','4','5','6','−','1','2','3','+','⌫','0','.','=']){const b=el('button',{},n);keys.append(b);b.onclick=()=>{if(n==='C'){a=null;op=null;fresh=true;display.value='0'}else if('÷×−+'.includes(n)){a=operate();display.value=String(a);op=n;fresh=true}else if(n==='='){const result=operate();display.value=Number.isFinite(result)?String(Number(result.toPrecision(12))):'Error';a=null;op=null;fresh=true}else if(n==='±')display.value=String(-Number(display.value));else if(n==='%')display.value=String(Number(display.value)/100);else if(n==='⌫')display.value=display.value.slice(0,-1)||'0';else{if(fresh||display.value==='Error'){display.value=n==='.'?'0.':n;fresh=false}else if(n!=='.'||!display.value.includes('.'))display.value=display.value==='0'&&n!=='.'?n:display.value+n}}}content.append(display,keys);status.textContent='Standard calculator'}
else if(id==='paint'){const tools=el('div',{className:'row'}),color=el('input',{type:'color',value:'#000000',title:'Brush color'}),size=el('select',{title:'Brush size'}),clear=el('button',{},'Clear'),save=el('button',{},'Save PNG');for(const n of [2,5,10,20])size.append(el('option',{value:n},n+' px'));tools.append(color,size,clear,save);const stage=el('div',{className:'paint-stage'}),canvas=el('canvas',{width:900,height:550});stage.append(canvas);content.append(tools,stage);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,900,550);let drawing=false;function point(e){const r=canvas.getBoundingClientRect();return[(e.clientX-r.left)*900/r.width,(e.clientY-r.top)*550/r.height]}canvas.onpointerdown=e=>{drawing=true;canvas.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...point(e));ctx.strokeStyle=color.value;ctx.lineWidth=Number(size.value);ctx.lineCap='round';ctx.lineTo(...point(e));ctx.stroke()};canvas.onpointermove=e=>{if(drawing){ctx.lineTo(...point(e));ctx.stroke()}};canvas.onpointerup=canvas.onpointercancel=()=>drawing=false;clear.onclick=()=>{ctx.fillStyle='#fff';ctx.fillRect(0,0,900,550)};save.onclick=()=>{const a=el('a',{download:'Painting.png',href:canvas.toDataURL()});a.click()};status.textContent='Choose a color and draw. Touch and mouse supported.'}
else if(id==='settings'){content.classList.add('settings');content.append(el('h3',{},'Sound effects'));const soundLabel=el('label'),mute=el('input',{type:'checkbox',checked:desktopSound.muted}),testSound=el('button',{},'Test notification sound');soundLabel.style.flexDirection='row';soundLabel.append(mute,el('span',{},'Mute all sound effects'));mute.onchange=()=>{desktopSound.setMuted(mute.checked);if(!mute.checked)desktopSound.play('notification')};testSound.onclick=()=>desktopSound.play('notification');content.append(soundLabel,testSound);content.append(el('h3',{},'Desktop appearance'));const swatches=el('div',{className:'swatches'});for(const c of ['#008080','#3a6ea5','#21452e','#552c63','#192e45','#000000']){const b=el('button',{className:'swatch',title:c});b.style.background=c;b.onclick=()=>{settings.color=c;document.documentElement.style.setProperty('--desk',c);saveSettings()};swatches.append(b)}content.append(swatches,el('h3',{},'AI connection'),el('p',{},'Use an HTTPS chat-completions endpoint that allows browser requests. Your key is kept in memory for this session only.'));for(const [label,prop,type,placeholder]of [['Endpoint URL','endpoint','url','https://your-provider.example/v1/chat/completions'],['Model','model','text','Provider model ID'],['API key','key','password','Session-only API key']]){const l=el('label',{},label),input=el('input',{type,placeholder,value:prop==='key'?key:settings[prop]||''});input.oninput=()=>{if(prop==='key')key=input.value;else{settings[prop]=input.value;saveSettings()}};l.append(input);content.append(l)}status.textContent='Appearance and endpoint saved on this browser.'}
else if(id==='chat'){const log=el('div',{className:'chat-log',role:'log'}),row=el('form',{className:'row'}),input=el('input',{placeholder:'Type a message…',ariaLabel:'Message',required:true}),send=el('button',{type:'submit'},'Send'),configure=el('button',{},'Connection settings');let messages=[];function message(role,text){const box=el('div',{className:'message'});box.append(el('b',{},role),el('span',{},text));log.append(box);log.scrollTop=log.scrollHeight}message('Desktop 95','Welcome. Open Connection settings to connect your AI provider, then send a message.');configure.onclick=()=>open('settings');row.append(input,send);content.append(configure,log,row);status.textContent='AI provider not connected';row.onsubmit=async e=>{e.preventDefault();if(!settings.endpoint||!settings.model){desktopSound.play('error');message('System','Enter an endpoint and model in Connection settings first.');open('settings');return}let url;try{url=new URL(settings.endpoint);if(url.protocol!=='https:')throw Error()}catch{desktopSound.play('error');message('System','The endpoint must be a valid HTTPS URL.');return}const text=input.value.trim();if(!text)return;message('You',text);messages.push({role:'user',content:text});input.value='';send.disabled=true;status.textContent='Connecting…';try{const headers={'Content-Type':'application/json'};if(key)headers.Authorization='Bearer '+key;const r=await fetch(url,{method:'POST',headers,body:JSON.stringify({model:settings.model,messages}),signal:AbortSignal.timeout(60000)});if(!r.ok)throw Error('Provider returned HTTP '+r.status);const data=await r.json(),answer=data.choices?.[0]?.message?.content;if(typeof answer!=='string')throw Error('Provider did not return a chat-completions response');desktopSound.play('notification');message('Assistant',answer);messages.push({role:'assistant',content:answer});status.textContent='Connected · '+settings.model}catch(error){desktopSound.play('error');messages.pop();message('System',error.message+'. Check your endpoint, key, model, and provider browser-access settings.');status.textContent='Connection failed'}finally{send.disabled=false;input.focus()}}}
else{const intro=el('div',{className:'welcome'});intro.innerHTML='<h1>Welcome to Desktop 95</h1><b>A familiar place to make things.</b><p>Your desktop is ready. Open an app from the icons or the Start menu.</p><ul><li>Chat with your AI provider</li><li>Write and save notes</li><li>Calculate, sketch, and make it yours</li></ul><p>Drag a title bar to move a window. Use the taskbar to switch between apps.</p>';const go=el('button',{},'Open AI Chat');go.onclick=()=>open('chat');content.append(intro,go);status.textContent='Desktop 95 · Personal edition'}
}
for(const [id,[glyph,name,color]]of Object.entries(apps)){const icon=el('button',{className:'icon',title:'Open '+name});const g=el('span',{className:'glyph'},glyph);g.style.color=color;icon.append(g,el('span',{},name));icon.onclick=()=>open(id);$('#icons').append(icon);const menu=el('button',{},glyph+'    '+name);menu.onclick=()=>open(id);$('#programs').append(menu)}
$('#start').onclick=()=>{desktopSound.play('menu');$('#start-menu').hidden=!$('#start-menu').hidden};document.addEventListener('pointerdown',e=>{if(!e.target.closest('#start-menu')&&!e.target.closest('#start'))$('#start-menu').hidden=true});document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#start-menu').hidden=true});function tick(){$('#clock').textContent=new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}tick();setInterval(tick,1000);if(settings.color)document.documentElement.style.setProperty('--desk',settings.color);open('welcome');
